/* @autogenerated */
import { fakeAsync, tick } from '@angular/core/testing';
import { config, of, Subject, throwError } from 'rxjs';
import { selectorProvider, SelectorProviderHandler } from './selector-provider';

describe('selectorProvider', () => {
  it('searches and updates values', fakeAsync(() => {
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => of([{ id: 1 }]),
      select: () => of(undefined),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    provider.search('test');

    tick();

    expect(provider.searching()).toBeFalse();
    expect(provider()).toEqual([{ id: 1 }]);
  }));

  it('selects and updates selection', fakeAsync(() => {
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => of([{ id: 1 }, { id: 2 }]),
      select: (value) => of(value ? { id: value } : undefined),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    provider.search('items');
    tick();

    provider.select(2);
    tick();

    expect(provider.selection()).toEqual({ id: 2 });
    expect(provider()?.find((item) => item.id === 2)).toEqual({ id: 2 });
  }));

  it('clears selection when value is null', fakeAsync(() => {
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => of([{ id: 1 }]),
      select: () => of(undefined),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    provider.select(null);
    tick();

    expect(provider.selection()).toBeNull();
    expect(provider()).toBeUndefined();
  }));

  it('treats falsy values (0, false, empty string) as valid selections', fakeAsync(() => {
    const cases: [number | boolean | string, string][] = [
      [0, 'zero'],
      [false, 'no'],
      ['', 'empty'],
    ];
    for (const [value, label] of cases) {
      const handler: SelectorProviderHandler<{ value: unknown; label: string }, unknown> = {
        search: () => of([]),
        select: (selected) => of({ value: selected, label }),
        equals: (one, other) => one === other,
        display: (item) => item.label,
        value: (item) => item.value,
      };

      const provider = selectorProvider(handler);
      provider.select(value);
      tick();

      expect(provider.selection()).toEqual({ value, label });
      expect(provider()).toEqual([{ value, label }]);
    }
  }));

  it('clears selection when value is undefined', fakeAsync(() => {
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => of([{ id: 1 }]),
      select: (value) => of({ id: value }),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    provider.select(1);
    tick();

    provider.select(undefined as unknown as null);
    tick();

    expect(provider.selection()).toBeNull();
    expect(provider()).toBeUndefined();
  }));

  it('prepends response when it is not already in the current list', fakeAsync(() => {
    // Covers: response && prev → true, but find() returns falsy → val.set([response, ...prev])
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => of([{ id: 1 }, { id: 2 }]),
      select: (value) => of({ id: value as number }),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    provider.search('items');
    tick();

    provider.select(99); // {id:99} is NOT in [{id:1},{id:2}]
    tick();

    expect(provider.selection()).toEqual({ id: 99 });
    expect(provider()![0]).toEqual({ id: 99 }); // prepended
    expect(provider()?.length).toBe(3);
  }));

  it('sets only the response when there is no prior list (val is undefined)', fakeAsync(() => {
    // Covers: response && prev → false (prev is undefined) → val.set([response])
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => of([]),
      select: (value) => of({ id: value as number }),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    // No search call → val() is undefined

    provider.select(5);
    tick();

    expect(provider.selection()).toEqual({ id: 5 });
    expect(provider()).toEqual([{ id: 5 }]);
  }));

  it('clears list when select handler returns undefined', fakeAsync(() => {
    // Covers: response && prev → false (response is undefined) → val.set(undefined)
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => of([{ id: 1 }]),
      select: () => of(undefined),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    provider.search('items');
    tick();

    provider.select(42); // truthy value but handler returns undefined
    tick();

    expect(provider()).toBeUndefined();
    expect(provider.selection()).toBeNull();
  }));

  it('exposes the search error without rethrowing it', fakeAsync(() => {
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => throwError(() => new Error('network error')),
      select: () => of(undefined),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    spyOn(console, 'error');
    const unhandled = jasmine.createSpy('onUnhandledError');
    const original = config.onUnhandledError;
    config.onUnhandledError = unhandled;
    try {
      provider.search('fail');
      tick();
    } finally {
      config.onUnhandledError = original;
    }

    expect(console.error).toHaveBeenCalledWith('Selector search failed', jasmine.any(Error));
    expect(unhandled).not.toHaveBeenCalled();
    expect(provider.error()).toEqual(jasmine.any(Error));
    expect(provider.searching()).toBeFalse();
  }));

  it('exposes the select error without rethrowing it', fakeAsync(() => {
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => of([{ id: 1 }]),
      select: () => throwError(() => new Error('select error')),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    spyOn(console, 'error');
    const unhandled = jasmine.createSpy('onUnhandledError');
    const original = config.onUnhandledError;
    config.onUnhandledError = unhandled;
    try {
      provider.select(1);
      tick();
    } finally {
      config.onUnhandledError = original;
    }

    expect(console.error).toHaveBeenCalledWith('Selector selection failed', jasmine.any(Error));
    expect(unhandled).not.toHaveBeenCalled();
    expect(provider.error()).toEqual(jasmine.any(Error));
    expect(provider.searching()).toBeFalse();
  }));

  it('clears the previous error when a new search starts', fakeAsync(() => {
    const results = new Subject<{ id: number }[]>();
    let fail = true;
    const handler: SelectorProviderHandler<{ id: number }, number> = {
      search: () => (fail ? throwError(() => new Error('network error')) : results),
      select: () => of(undefined),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    spyOn(console, 'error');
    provider.search('fail');
    tick();
    expect(provider.error()).toBeTruthy();

    fail = false;
    provider.search('ok');
    expect(provider.error()).toBeNull();
    results.next([{ id: 1 }]);
    results.complete();
    tick();
    expect(provider()).toEqual([{ id: 1 }]);
  }));

  it('deduplicates the selected item using handler.equals over handler.value', fakeAsync(() => {
    const handler: SelectorProviderHandler<{ id: number; label?: string }, number> = {
      search: () => of([{ id: 1, label: 'one' }, { id: 2 }]),
      // Same id but a different shape: JSON comparison would wrongly prepend it
      select: (value) => of({ id: value, label: 'fresh' }),
      equals: (one, other) => one === other,
      display: (item) => String(item.id),
      value: (item) => item.id,
    };

    const provider = selectorProvider(handler);
    provider.search('items');
    tick();

    provider.select(1);
    tick();

    expect(provider()?.length).toBe(2);
    expect(provider.selection()).toEqual({ id: 1, label: 'fresh' });
  }));
});
